// Pseudo routing snippet
if (!isValid(event)) {
  const dlqTopic = `dlq/tenant-${event.tenant_id}`;
  publish(dlqTopic, { event_id: event.id, tenant_id: event.tenant_id, reason: 'validation_error' });
} else {
  routeToNormalPath(event);
}
```

